export type MemberSearchResult = { id: string; name: string };

// Desk volunteers find a member by part of their name.
// Results show who a member is, never how to contact them.
export function searchMembers(db: Database, namePart: string): MemberSearchResult[] {
  const query = db.query("SELECT id, name FROM members WHERE name LIKE ? ORDER BY name");
  return query.all(`%${namePart}%`) as MemberSearchResult[];
}

